-- =============================================================================
-- Showroom catalog: 121 homes, 116 businesses and 102 luxury items
-- (cars, motorbikes, boats and yachts, helicopters, light aircraft and jets).
--
-- Generated from scripts/catalog/data/*.csv by scripts/catalog/catalog.py, which works out
-- rent, upkeep, business income, running costs, depreciation and lease income.
-- No photos yet: fill in scripts/catalog/data/photos_todo.csv and run
--   python3 scripts/catalog/catalog.py photos scripts/catalog/data/photos_todo.csv -o photos.sql
--
-- Safe to run more than once: items whose name already exists are skipped.
-- =============================================================================
begin;

-- Photo columns: businesses get a photo, and every catalog gets a credit line for photos
-- whose licence asks for one (the app shows it small on the card).
alter table public.assets add column if not exists image_url text;
alter table public.assets add column if not exists image_credit text;
alter table public.home_listings add column if not exists image_credit text;
alter table public.liability_items add column if not exists image_credit text;

-- Homes: 121 rows (existing names are skipped)
